// Stops events from a given element propagating to and being consumed by leaflet.
// Generated by Claude Opus 5.5, intended to correct behavour specifically on Mobile Firefox.

import { isPlatformBrowser } from '@angular/common';
import { AfterViewInit, Directive, ElementRef, NgZone, OnDestroy, PLATFORM_ID, inject } from '@angular/core';

@Directive({
  selector: '[appStopMapPropagation]',
  standalone: true,
})
export class StopMapPropagationDirective implements AfterViewInit, OnDestroy {
  private readonly el = inject<ElementRef<HTMLElement>>(ElementRef);
  private readonly zone = inject(NgZone);
  private readonly isBrowser = isPlatformBrowser(inject(PLATFORM_ID));

  private readonly events = ['pointerdown', 'pointerup', 'touchstart', 'touchend', 'mousedown', 'dblclick'];
  private readonly stop = (e: Event) => e.stopPropagation();

  async ngAfterViewInit(): Promise<void> {
    if (!this.isBrowser) return;

    const host = this.el.nativeElement;

    // Extra pointer/touch blocking, outside Angular to avoid needless
    // change detection on every touch
    this.zone.runOutsideAngular(() => {
      this.events.forEach((type) => host.addEventListener(type, this.stop, { passive: true }));
    });

    // Load Leaflet only in the browser (it references window on import)
    const L = await import('leaflet');
    L.DomEvent.disableClickPropagation(host);
    L.DomEvent.disableScrollPropagation(host);
  }

  ngOnDestroy(): void {
    if (!this.isBrowser) return;

    const host = this.el.nativeElement;
    this.events.forEach((type) => host.removeEventListener(type, this.stop));
  }
}
